use split_decls_genesis :: ourprelude :: * ; use std :: fmt ; use std :: hash :: Hash ; use super :: map :: SsoHashMap ; #[doc = " Small-storage-optimized implementation of a set."] #[doc = ""] #[doc = " Stores elements in a small array up to a certain length"] #[doc = " and switches to `HashSet` when that length is exceeded."] #[derive (Clone)] pub struct SsoHashSet < T > { map : SsoHashMap < T , () > , } #[doc = " Adapter function used to return"] #[doc = " result if SsoHashMap functions into"] #[doc = " result SsoHashSet should return."] #[inline (always)] fn entry_to_key < K , V > ((k , _v) : (K , V)) -> K { k } impl < T > SsoHashSet < T > { #[doc = " Creates an empty `SsoHashSet`."] #[inline] pub fn new () -> Self { Self { map : SsoHashMap :: new () } } #[doc = " Creates an empty `SsoHashSet` with the specified capacity."] #[inline] pub fn with_capacity (cap : usize) -> Self { Self { map : SsoHashMap :: with_capacity (cap) } } #[doc = " Clears the set, removing all values."] #[inline] pub fn clear (& mut self) { self . map . clear () } #[doc = " Returns the number of elements the set can hold without reallocating."] #[inline] pub fn capacity (& self) -> usize { self . map . capacity () } #[doc = " Returns the number of elements in the set."] #[inline] pub fn len (& self) -> usize { self . map . len () } #[doc = " Returns `true` if the set contains no elements."] #[inline] pub fn is_empty (& self) -> bool { self . map . is_empty () } #[doc = " An iterator visiting all elements in arbitrary order."] #[doc = " The iterator element type is `&'a T`."] #[inline] pub fn iter (& self) -> impl Iterator < Item = & T > { self . into_iter () } #[doc = " Clears the set, returning all elements in an iterator."] #[inline] pub fn drain (& mut self) -> impl Iterator < Item = T > { self . map . drain () . map (entry_to_key) } } impl < T : Eq + Hash > SsoHashSet < T > { #[doc = " Reserves capacity for at least `additional` more elements to be inserted"] #[doc = " in the `SsoHashSet`. The collection may reserve more space to avoid"] #[doc = " frequent reallocations."] #[inline] pub fn reserve (& mut self , additional : usize) { self . map . reserve (additional) } #[doc = " Shrinks the capacity of the set as much as possible. It will drop"] #[doc = " down as much as possible while maintaining the internal rules"] #[doc = " and possibly leaving some space in accordance with the resize policy."] #[inline] pub fn shrink_to_fit (& mut self) { self . map . shrink_to_fit () } #[doc = " Retains only the elements specified by the predicate."] #[inline] pub fn retain < F > (& mut self , mut f : F) where F : FnMut (& T) -> bool , { self . map . retain (| k , _v | f (k)) } #[doc = " Removes and returns the value in the set, if any, that is equal to the given one."] #[inline] pub fn take (& mut self , value : & T) -> Option < T > { self . map . remove_entry (value) . map (entry_to_key) } #[doc = " Returns a reference to the value in the set, if any, that is equal to the given value."] #[inline] pub fn get (& self , value : & T) -> Option < & T > { self . map . get_key_value (value) . map (entry_to_key) } #[doc = " Adds a value to the set."] #[doc = ""] #[doc = " Returns whether the value was newly inserted. That is:"] #[doc = ""] #[doc = " - If the set did not previously contain this value, `true` is returned."] #[doc = " - If the set already contained this value, `false` is returned."] #[inline] pub fn insert (& mut self , elem : T) -> bool { self . map . insert (elem , ()) . is_none () } #[doc = " Removes a value from the set. Returns whether the value was"] #[doc = " present in the set."] #[inline] pub fn remove (& mut self , value : & T) -> bool { self . map . remove (value) . is_some () } #[doc = " Returns `true` if the set contains a value."] #[inline] pub fn contains (& self , value : & T) -> bool { self . map . contains_key (value) } } impl < T : Eq + Hash > FromIterator < T > for SsoHashSet < T > { fn from_iter < I : IntoIterator < Item = T > > (iter : I) -> SsoHashSet < T > { let mut set : SsoHashSet < T > = Default :: default () ; set . extend (iter) ; set } } impl < T > Default for SsoHashSet < T > { #[inline] fn default () -> Self { Self :: new () } } impl < T : Eq + Hash > Extend < T > for SsoHashSet < T > { fn extend < I > (& mut self , iter : I) where I : IntoIterator < Item = T > , { for val in iter . into_iter () { self . insert (val) ; } } #[inline] fn extend_one (& mut self , item : T) { self . insert (item) ; } #[inline] fn extend_reserve (& mut self , additional : usize) { self . map . extend_reserve (additional) } } impl < 'a , T > Extend < & 'a T > for SsoHashSet < T > where T : 'a + Eq + Hash + Copy , { #[inline] fn extend < I : IntoIterator < Item = & 'a T > > (& mut self , iter : I) { self . extend (iter . into_iter () . cloned ()) ; } #[inline] fn extend_one (& mut self , & item : & 'a T) { self . insert (item) ; } #[inline] fn extend_reserve (& mut self , additional : usize) { Extend :: < T > :: extend_reserve (self , additional) } } impl < T > IntoIterator for SsoHashSet < T > { type IntoIter = std :: iter :: Map < < SsoHashMap < T , () > as IntoIterator > :: IntoIter , fn ((T , ())) -> T > ; type Item = < Self :: IntoIter as Iterator > :: Item ; #[inline] fn into_iter (self) -> Self :: IntoIter { self . map . into_iter () . map (entry_to_key) } } impl < 'a , T > IntoIterator for & 'a SsoHashSet < T > { type IntoIter = std :: iter :: Map < < & 'a SsoHashMap < T , () > as IntoIterator > :: IntoIter , fn ((& 'a T , & 'a ())) -> & 'a T , > ; type Item = < Self :: IntoIter as Iterator > :: Item ; #[inline] fn into_iter (self) -> Self :: IntoIter { self . map . iter () . map (entry_to_key) } } impl < T > fmt :: Debug for SsoHashSet < T > where T : fmt :: Debug , { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_set () . entries (self . iter ()) . finish () } }